    fn make_session_with_send_capacity(
        capacity: usize,
    ) -> (WorldSession, flume::Receiver<Vec<u8>>) {
        let (_pkt_tx, pkt_rx) = flume::bounded::<WorldPacket>(1);
        let (send_tx, send_rx) = flume::bounded::<Vec<u8>>(capacity);
        let mut session = WorldSession::new(
            1,
            "TestAccount".into(),
            0,
            2,
            9,
            54261,
            vec![0u8; 40],
            "esES".into(),
            pkt_rx,
            send_tx,
        );
        session.set_item_guid_generator_like_cpp(Arc::new(ObjectGuidGenerator::new(
            HighGuid::Item,
            1,
        )));
        session.set_equipment_set_guid_generator_like_cpp(Arc::new(
            EquipmentSetGuidGeneratorLikeCpp::new(1),
        ));
        (session, send_rx)
    }

