    fn strength_item_stats_store(entry_id: u32, amount: i16) -> ItemStatsStore {
        ItemStatsStore::from_parts(
            [(
                entry_id,
                ItemStatEntry {
                    stats: std::array::from_fn(|i| {
                        if i == 0 {
                            (ItemModType::Strength as i8, amount)
                        } else {
                            (ItemModType::None as i8, 0)
                        }
                    }),
                    resistances: [0; 7],
                    armor: 0,
                },
            )],
            [],
        )
    }

