        assert_eq!(pkt.read_uint32().unwrap(), TACT_KEY_TABLE_HASH_LIKE_CPP);
        assert_eq!(pkt.read_int32().unwrap(), 3909);
        let _timestamp = pkt.read_int32().unwrap();
